// Handler registry: event name -> ordered array of closures.
mapping handlers = ([]);

int first_ran = 0;
int second_ran = 0;

void register_handler(string event, function f) {
  if (!handlers[event]) {
    handlers[event] = ({ });
  }
  handlers[event] += ({ f });
}

// Runs handlers in registration order; a non-zero return stops the chain.
int run_event(string event, string arg) {
  if (!handlers[event]) {
    return 0;
  }
  foreach (function f in handlers[event]) {
    if (evaluate(f, arg)) {
      return 1;
    }
  }
  return 0;
}

